/* Extends the existing F9 dashboard, does not replace its reports/environment/Gunner tools. */

(function(root){'use strict';const P=root.NeonCombat.Playback265;let s,bridge,box,bar,detail,lastPaint=0;
function button(parent,label,fn,disabled=false,title=''){const b=document.createElement('button');b.type='button';b.textContent=label;b.disabled=disabled;b.title=title;b.onclick=fn;parent.append(b);return b;}
function refresh(force=false){if(!s||!bar)return;const now=performance.now();if(!force&&now-lastPaint<100)return;lastPaint=now;const r=P.view(s);bar.querySelector('[data-clock]').textContent=`${s.paused?'PAUSED':'RUNNING'} · ${s.speed}× · frame ${s.frame} · ${s.elapsed.toFixed(3)}s simulation · ${s.records.length}/900 recorded`;
 if(!box)return;const scrub=box.querySelector('[data-scrub]');scrub.min=s.records[0]?.frame||0;scrub.max=s.records.at(-1)?.frame||0;scrub.value=s.selected??s.frame;box.querySelector('[data-review]').textContent=s.selected!=null?`REVIEW ONLY · recorded frame ${s.selected}; live world remains at ${s.frame}`:'LIVE · recorded history never changes the current world';
 const focus=box.querySelector('[data-focus]'),old=focus.value,actors=r?.actors||[];if(focus.dataset.ids!==actors.map(e=>e.id).join(',')){focus.replaceChildren();for(const e of actors){const o=document.createElement('option');o.value=e.id;o.textContent=e.name+(e.id===r.heroId?' · hero':' · enemy');focus.append(o);}focus.dataset.ids=actors.map(e=>e.id).join(',');if(actors.some(e=>String(e.id)===old))focus.value=old;}
 const chosen=actors.find(e=>String(e.id)===focus.value)||actors[0],rows=actors.filter(e=>e===chosen||e.id===r?.heroId);const timeline=box.querySelector('[data-timeline]');timeline.replaceChildren();for(const actor of rows){const line=document.createElement('p');line.textContent=actor.name+' · ';for(const frame of s.records.slice(-120)){const a=frame.actors.find(e=>e.id===actor.id);if(!a)continue;const mark=document.createElement('button');mark.type='button';mark.className='phase265 '+(/startup/.test(a.phase)?'startup':a.phase==='active'?'active':/recovery/.test(a.phase)?'recovery':'other');mark.title=`frame ${frame.frame}: ${a.action||'no action'} / ${a.phase} · last contact ${a.reactionDiagnostics?.contactOutcome??'none'} · ΔHP ${a.hpDelta}`;mark.setAttribute('aria-label',mark.title);mark.onclick=()=>{P.pause(s);P.select(s,frame.frame);refresh(true);};line.append(mark);}timeline.append(line);}
 detail.textContent=JSON.stringify({record:r&&{frame:r.frame,gameTime:r.gameTime,projectiles:r.projectiles},focus:chosen,hero:rows.find(e=>e.id===r?.heroId),notes:['Configured contacts are opportunities, not confirmed hits. Gate11 has registered native-window/contact adapters; unsupported spans remain N/A.','Only fresh renderer receipts supply animation indices; unknown indices stay N/A. HP delta is observed change.','Contact outcome describes the last resolved contact; physical state describes this recorded frame.','Stun-clear timestamps and elapsed seconds observe remaining stun/shock reaching zero. Launch may clear stun immediately; these are not flight, knockdown or total recovery durations. Raw releasedAt/actualSeconds are preserved.'],queuedInputs:s.queue.length,droppedInputs:s.dropped},null,2);}
function mount(parent){if(!s)return;if(!box){box=document.createElement('section');box.id='precision265';box.innerHTML='<h3>PRECISION LAB · GATE A</h3><p>F9 or L3 + Options opens this panel · F8 collision references. Enable developer playback to use the fixed 60 Hz clock. No balance settings change.</p><div data-controls></div><p data-review></p><label>Recorded frame <input data-scrub type="range" min="0" max="0" value="0"></label><label>Timeline focus <select data-focus></select></label><div data-timeline></div><p>Last contact outcome is history. Physical state describes the recorded frame. Stun-clear time observes stun/shock clearance, not flight or total recovery.</p><details><summary>Captured runtime frame</summary><pre></pre></details><p>Rewind and move/duel restart are unavailable: full native state restoration is not yet certified. Recorded navigation inspects telemetry only.</p><nav data-links></nav>';detail=box.querySelector('pre');const c=box.querySelector('[data-controls]');button(c,'Enable playback',()=>{P.enable(s);P.reset(s);bar.hidden=false;refresh(true);});button(c,'Return to normal / disable',()=>{P.enable(s,false);bar.hidden=true;refresh(true);});button(c,'Previous recorded frame',()=>{P.pause(s);const rows=s.records,i=rows.findIndex(r=>r.frame===(s.selected??s.frame));if(i>0)P.select(s,rows[i-1].frame);refresh(true);});button(c,'Live frame',()=>{s.selected=null;refresh(true);});button(c,'Rewind simulation',null,true,'Full-state restoration is not certified');button(c,'Restart current move',null,true,'Cannot safely restore the pre-move state');button(c,'Restart current duel',null,true,'Use an existing isolated duel lab; no generic duel snapshot exists');button(c,'Restart current section',()=>{if(confirm('Restart this section? Current encounter progress and uncollected items may be lost.')){bridge.restart();P.reset(s);refresh(true);}});button(c,'Export recorded frames',()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({build:265,kind:'observational-telemetry-not-replay',records:s.records},null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='urban-fracture265-frames.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
 const links=box.querySelector('[data-links]');for(const [href,label]of [['combat-review248.html','Counter / weapon duel lab'],['grab223.html','Grab threshold lab'],['qa242.html','QA screenshots'],['animation189.html','Animation lab']]){const a=document.createElement('a');a.href='./'+href;a.target='_blank';a.rel='noopener';a.textContent=label;links.append(a);}box.querySelector('[data-scrub]').oninput=e=>{P.pause(s);P.select(s,e.target.value);refresh(true);};box.querySelector('[data-focus]').onchange=()=>refresh(true);}
 if(box.parentNode!==parent)parent.prepend(box);refresh(true);}
function bind(g,b){s=P.create(g);bridge=b;bar=document.createElement('section');bar.id='playback265';bar.hidden=true;bar.setAttribute('aria-label','Developer simulation playback');const speed=document.createElement('select');speed.setAttribute('aria-label','Simulation speed');for(const v of P.SPEEDS){const o=document.createElement('option');o.value=v;o.textContent=v+'×';speed.append(o);}speed.value='1';speed.onchange=()=>{P.speed(s,speed.value);refresh(true);};bar.append(speed);button(bar,'Pause simulation',()=>{P.pause(s);refresh(true);});button(bar,'Resume simulation',()=>{P.pause(s,false);refresh(true);});for(const n of [1,5,10])button(bar,'+'+n+' frame'+(n>1?'s':''),()=>{P.pause(s);P.step(s,n,bridge.input(),bridge.tick,bridge.allowed());bridge.after();refresh(true);});const clock=document.createElement('span');clock.dataset.clock='';bar.append(clock);document.body.append(bar);root.PrecisionLab265.state=s;}
function enablePractice282(speed=1){if(!s)return;P.enable(s);P.speed(s,speed);P.reset(s);bar.hidden=false;bar.querySelector('select').value=String(s.speed);refresh(true);}
root.PrecisionLab265={bind,mount,refresh,enablePractice282,get state(){return s;},set state(v){s=v;}};
})(globalThis);
